#!/usr/bin/env python3import sysfrom pathlib import Pathtarget = Path("bin/agent/prompts.py")raw = target.read_bytes()out = []out.append(f"File size: {len(raw)}")out.append(f"Has CRLF: {b'\r\n' in raw}")src = raw.decode("utf-8")src_norm = src.replace("\r\n", "\n")out.append(f"_prompt_node found: {'def _prompt_node' in src_norm}")out.append(f"return prompt found: {'    return prompt\n' in src_norm}")out.append(f"read_prompts_config found: {'def read_prompts_config(' in src_norm}")out.append(f"--reset-system found: {'--reset-system' in src_norm}")idx = src_norm.find("def _prompt_node")if idx >= 0:    snippet = src_norm[idx:idx+300]    out.append(f"Context: {repr(snippet[:200])}")# Check if _write_prompts_xml is called but not definedout.append(f"_write_prompts_xml call: {'_write_prompts_xml(tree, target)' in src_norm}")out.append(f"def _write_prompts_xml: {'def _write_prompts_xml' in src_norm}")Path(".agentic/debug_output.txt").write_text("\n".join(out), encoding="utf-8")